-- Anousith directory: 825 rows from the user-provided shipping_branches_import_partial.sql.
-- Imports ANOUSITH only. Existing HAL/UNITEL rows and saved shipping bills are preserved.
-- Source IDs are the key: two source records share a branch code.
-- Safe to rerun: existing IDs/created_at/manual is_active flags are preserved.
begin;
set local standard_conforming_strings = on;

create table if not exists public.shipping_branches (
  id uuid primary key default gen_random_uuid(),
  company text not null check (company in ('HAL', 'ANOUSITH', 'UNITEL')),
  source_id text,
  branch_code text,
  branch_name text not null,
  province text,
  district text,
  village text,
  address text,
  phone text,
  latitude double precision,
  longitude double precision,
  source_url text,
  source_payload jsonb,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- Also supports a table previously created by the attached partial import.
alter table public.shipping_branches add column if not exists is_active boolean not null default true;
create unique index if not exists shipping_branches_company_source_id_key
  on public.shipping_branches (company, source_id);
create index if not exists shipping_branches_company_active_idx
  on public.shipping_branches (company, is_active, id);
create index if not exists idx_shipping_branches_province on public.shipping_branches (province);
create index if not exists idx_shipping_branches_name on public.shipping_branches (branch_name);

-- The authenticated app endpoint uses the server service-role client.
-- Raw address/contact/source data is not exposed directly to browser roles.
alter table public.shipping_branches enable row level security;
revoke all on public.shipping_branches from anon, authenticated;
grant select, insert, update, delete on public.shipping_branches to service_role;

insert into public.shipping_branches (company, source_id, branch_code, branch_name, province, district, village, address, phone, source_url, source_payload)
select seed.company, seed.source_id, seed.branch_code, seed.branch_name, seed.province, seed.district, seed.village, seed.address, seed.phone, seed.source_url, seed.source_payload
